const DATA={"grammar":{"Block 1 — The Basics":["Subject Pronouns","Verb to be: am / is / are","Possessive Adjectives","Articles: a / an","Singular and Plural Nouns","Demonstratives","Basic Adjective Position","Possessive 's"],"Block 2 — Present Simple":["Present Simple Affirmative","Present Simple Negative","Present Simple Questions","Do / Does","Question Words","Adverbs of Frequency","Basic Word Order","Have / Have Got"],"Block 3 — Places and Possession":["There is / There are","Prepositions of Place","Prepositions of Time","Object Pronouns","Possessive Pronouns","Some / Any"],"Block 4 — Actions and Ability":["Can / Can't","Can for Permission","Imperatives","Present Continuous","Present Simple vs Present Continuous"],"Block 5 — Quantity":["Countable and Uncountable Nouns","Much / Many","A Lot Of","A Few / A Little","How Much / How Many"],"Block 6 — The Past":["Was / Were","Past Simple Regular Verbs","Common Irregular Verbs","Past Simple Negative","Past Simple Questions","There Was / There Were"],"Block 7 — Comparisons":["Comparative Adjectives","Superlative Adjectives","Basic Adverbs of Manner"],"Block 8 — Future":["Be Going To","Basic Will","Would Like","Basic Offers with Shall"],"Block 9 — Connecting Ideas":["And / But / Or","Because / So","Basic Infinitive of Purpose","Common Verb + Infinitive / -ing","Articles Review","Full A1 Grammar Review"]},"vocabulary":{"Block 1 — Personal Information":["Greetings","Introductions","Alphabet","Spelling","Numbers","Countries","Nationalities","Languages","Personal Information"],"Block 2 — People":["Family","Friends","Jobs","Appearance","Body Parts","Clothes","Colors","Feelings","Personality Adjectives"],"Block 3 — Daily Life":["Daily Routines","Days","Months","Dates","Time","Parts of the Day","Everyday Activities"],"Block 4 — Home":["House","Rooms","Furniture","Household Objects","Chores"],"Block 5 — Food":["Food","Drinks","Meals","Restaurants","Basic Cooking Vocabulary"],"Block 6 — Places and Travel":["Places in Town","Buildings","Transport","Directions","Basic Travel Vocabulary"],"Block 7 — Nature and Free Time":["Weather","Seasons","Animals","Nature","Hobbies","Sports","Music","TV and Movies"],"Block 8 — Study and Work":["School","Classroom Objects","Study Vocabulary","Basic Workplace Vocabulary"],"Block 9 — Shopping":["Shopping","Money","Prices","Shops","Sizes"],"Block 10 — Core Vocabulary":["Common Verbs","Common Adjectives","Common Nouns","Basic Adverbs","Everyday Expressions"]},"topics":{"Speaking":["Introduce Yourself","Spell Your Name","Give Personal Information","Talk About Your Family","Say Where You Are From","Talk About Studies or Work","Talk About Your Routine","Talk About Likes and Dislikes","Describe a Person","Describe Your House","Describe Your Town","Talk About the Weather","Talk About Hobbies","Order Food","Ask for Prices","Buy Something","Ask for Directions","Give Directions","Talk About Yesterday","Talk About Future Plans","Basic Conversation Practice","Final A1 Speaking Challenge"],"Listening":["Alphabet and Spelling","Names","Numbers","Phone Numbers","Prices","Times","Dates","Personal Information","Introductions","Daily Routines","Short Conversations","Shopping","Food Orders","Directions","Weather","Family Descriptions","Simple Announcements","A1 Listening Review"],"Reading":["Signs","Notices","Posters","Menus","Timetables","Forms","Ads","Text Messages","Short Emails","Personal Profiles","Simple Descriptions","Short Stories","Basic Instructions","Simple Travel Information","A1 Reading Review"],"Writing":["Basic Sentences","Capital Letters and Punctuation","Personal Information Forms","Personal Profile","Short Message","Simple Email","Describe Yourself","Describe Your Family","Describe Your Routine","Describe Your House","Likes and Dislikes","Write About Yesterday","Write About Future Plans","Short Paragraph","A1 Writing Challenge"],"Pronunciation":["Alphabet","Basic Vowel Sounds","Basic Consonant Sounds","Common Difficult Sounds","Contractions","Final -s","Final -ed","Word Stress","Sentence Stress","Basic Linking","Question Intonation","A1 Pronunciation Review"],"Use of English":["Multiple Choice","Fill in the Blanks","Sentence Order","Find the Mistake","Complete the Dialogue","Choose the Correct Word","Grammar + Vocabulary","Short Text with Gaps","Basic Sentence Transformation","A1 Mixed Challenge"],"Final Review":["Grammar Test","Vocabulary Test","Listening Test","Reading Test","Writing Challenge","Speaking Challenge","Use of English Test","Final A1 Exam"]},"aviation":{"Starter":["Aviation Alphabet","Numbers and Flight Levels","Time and UTC","Basic Radio Words","Airport Basics"],"Pilot Vocabulary":["Cockpit","Flight Controls","Engine","Instruments","Runway and Taxiway","Phases of Flight"],"Weather":["Wind","Visibility","Clouds","Temperature","Basic METAR Vocabulary","Weather Hazards"],"Aircraft":["Aircraft Parts","Cessna 152 Basics","Preflight Vocabulary","Basic Systems","Performance Words"],"ATC":["Call Signs","Readbacks","Taxi Instructions","Takeoff and Landing","Traffic Information","Basic ATC Exchanges"],"Navigation":["Cardinal Directions","Heading and Track","Altitude","Distance","Basic Navigation Instructions","Position Reports"]}};
const app=document.querySelector("#app");
const esc=s=>String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const card=(title,sub,href)=>`<div class="card" onclick="location.hash='${href}'"><span class="pill">${esc(sub||"")}</span><h3>${esc(title)}</h3></div>`;
const hero=(title,p)=>`<section class="hero"><h1>${title}</h1><p>${p}</p></section>`;
const back=(href,label)=>`<button class="back" onclick="location.hash='${href}'">← ${label}</button>`;

const PO_ITEMS=[{id:"fish",name:"Fish / Pescado",icon:"🐟",price:25},{id:"tuna",name:"Tuna / Atún",icon:"🥫",price:40},{id:"chicken",name:"Chicken / Pollo",icon:"🍗",price:55},{id:"bow",name:"Bow / Moño",icon:"🎀",price:90},{id:"ball",name:"Ball / Pelota",icon:"🧶",price:65}];
const poDefault=()=>({name:"Po",gender:"female",eyes:"violet",fur:"cream",coins:0,inventory:{},fed:0,accessory:"none",earned:[]});
function poLoad(){try{const d=JSON.parse(localStorage.getItem("englishapp:po")||"{}");return {...poDefault(),...d,inventory:d.inventory||{},earned:Array.isArray(d.earned)?d.earned:[]}}catch{return poDefault()}}
function poSave(d){try{localStorage.setItem("englishapp:po",JSON.stringify(d))}catch{}}
function poAward(lessonId){const d=poLoad();if(d.earned.includes(lessonId))return false;d.earned.push(lessonId);d.coins+=50;poSave(d);return true}
function poRoom(){const d=poLoad();const clean=t=>esc(String(t));const food=PO_ITEMS.filter(x=>["fish","tuna","chicken"].includes(x.id));app.innerHTML=`
<div class="po-page po-redesign">
 <div class="po-head"><div><span class="po-kicker">🐾 ENGLISHAPP · YOUR COMPANION</span><h1>✨ Crea tu compañero</h1><p>Elige su nombre, su versión y su apariencia. Después podrás jugar y aprender con él.</p></div><div class="po-wallet">🪙 <strong>${d.coins}</strong> coins</div></div>
 <div class="po-showcase"><div class="po-showcase-main"><div class="po-showcase-title"><span class="po-script">Po ♡</span><p>Tu compañero de inglés</p><span>♡ Curioso &nbsp; ♡ Tranquilo &nbsp; ♡ Cariñoso</span></div><div class="po-showcase-cat"><img src="po-cat.svg" alt="Po, tu compañero gatito"/></div><div class="po-showcase-caption">Hi! Ready to learn today? ♡</div></div><div class="po-expressions" id="poExpressions"><h2>Expresiones de Po</h2><div class="po-expression-grid">${["Normal","Curioso","Atento","Sorprendido","Feliz","Guiñando","Pensando","Tranquilo","Travieso","Dormido","Con audífonos","Emocionado"].map((label,i)=>`<button type="button" class="po-expression" data-expression="${i}"><span class="po-expression-image"><img src="po-cat.svg" alt="Po"/></span><small>${label}</small></button>`).join("")}</div></div></div><div class="po-columns" id="poRoomSection"><section class="po-room"><div class="po-room-top">✦ My Cat's Room <span>☀️ Cozy corner</span></div><div class="po-cat-stage"><span class="po-sparkle">✦ ♡ ✧</span><img src="po-cat.svg" alt="Po, a warm-blond cream cat with natural feline features and a lavender hoodie" class="po-cat-image"/><span class="po-accessory">${d.accessory==="bow"?"🎀":d.accessory==="ball"?"🧶":""}</span></div><div class="po-speech" id="poSpeech">Hi! I'm ${clean(d.name)}. Let's learn together! 💜<small>¡Aprendamos juntos!</small></div><div class="po-room-actions"><button id="poPet">♡ Pet / Acariciar</button><button id="poTalk">🔊 Say hello</button></div><p class="po-room-foot">🐾 Fed ${d.fed} times · No daily penalties / Sin castigos por faltar</p></section>
 <section class="po-controls"><div class="po-panel"><h2>✨ Make it yours</h2><label for="poName">Cat's name / Nombre</label><input id="poName" maxlength="24" value="${clean(d.name)}" placeholder="Po"/><label for="poGender">Version / Versión</label><select id="poGender"><option value="female" ${d.gender==="female"?"selected":""}>♀ Femenina</option><option value="male" ${d.gender==="male"?"selected":""}>♂ Masculina</option></select><label for="poFur">Pelaje / Fur</label><select id="poFur"><option value="cream" ${d.fur==="cream"?"selected":""}>Crema y miel (original)</option><option value="honey" ${d.fur==="honey"?"selected":""}>Miel dorada</option><option value="pearl" ${d.fur==="pearl"?"selected":""}>Crema perlado</option></select><label for="poEyes">Ojos / Eyes</label><select id="poEyes"><option value="violet" ${d.eyes==="violet"?"selected":""}>Violeta suave</option><option value="green" ${d.eyes==="green"?"selected":""}>Verdes</option><option value="amber" ${d.eyes==="amber"?"selected":""}>Ámbar</option><option value="blue" ${d.eyes==="blue"?"selected":""}>Azules</option></select><button id="poSaveProfile">Save changes / Guardar</button><p class="po-hint">Both versions keep a natural cat appearance. Ambas versiones mantienen apariencia felina.</p></div>
 <div class="po-panel"><h2>👗 Ropita y accesorios</h2><div class="po-outfits">${[["none","Hoodie clásico","💜"],["bow","Con moño","🎀"],["ball","Con juguete","🧶"]].map(([id,name,icon])=>`<button type="button" data-outfit="${id}" class="${d.accessory===id?"active":""}"><span>${icon}</span><small>${name}</small></button>`).join("")}</div></div><div class="po-panel"><h2>🥣 Feed your cat</h2><p class="po-hint">Buy food in the shop, then feed your companion.</p><div class="po-inventory">${food.map(x=>`<button class="po-food" data-feed="${x.id}"><span>${x.icon}</span><b>${clean(x.name)}</b><small>Owned: ${d.inventory[x.id]||0}</small></button>`).join("")}</div></div></section></div>
 <section class="po-shop" id="poShopSection"><div class="po-shop-title"><div><span class="po-kicker">THE LITTLE SHOP</span><h2>🛍️ Po's Shop</h2><p>Spend coins earned by completing lessons.</p></div><span class="po-wallet">🪙 ${d.coins}</span></div><div class="po-shop-grid">${PO_ITEMS.map(x=>`<div class="po-product"><span class="po-product-icon">${x.icon}</span><strong>${clean(x.name)}</strong><span>🪙 ${x.price}</span><button data-buy="${x.id}">Buy / Comprar</button></div>`).join("")}</div></section>
 <div class="po-notice" id="poNotice" role="status" aria-live="polite"></div>
</div>`;
// Personalization first. Keep secondary features behind clear destinations.
const page=document.querySelector(".po-redesign"),showcase=page.querySelector(".po-showcase"),profile=page.querySelector(".po-controls .po-panel");
showcase.querySelector(".po-showcase-main").appendChild(profile);
const menu=document.createElement("nav");menu.className="po-destinations";menu.setAttribute("aria-label","Po's places");menu.innerHTML='<button type="button" data-po-panel="room">⌂ <b>Su casita</b><small>Visita su habitación</small></button><button type="button" data-po-panel="expressions">♡ <b>Expresiones</b><small>Descubre sus gestos</small></button><button type="button" data-po-panel="shop">✦ <b>Tienda</b><small>Comida y accesorios</small></button>';showcase.after(menu);
const openPanel=id=>{page.classList.toggle("po-show-room",id==="room");page.classList.toggle("po-show-expressions",id==="expressions");page.classList.toggle("po-show-shop",id==="shop");menu.querySelectorAll("button").forEach(b=>b.classList.toggle("active",b.dataset.poPanel===id));if(id){document.querySelector(id==="room"?"#poRoomSection":id==="expressions"?"#poExpressions":"#poShopSection").scrollIntoView({behavior:"smooth",block:"start"})}};
menu.querySelectorAll("button").forEach(b=>b.onclick=()=>openPanel(b.classList.contains("active")?"":b.dataset.poPanel));
page.dataset.fur=d.fur;page.dataset.eyes=d.eyes;
const notify=(msg)=>{document.querySelector("#poNotice").textContent=msg};document.querySelectorAll("[data-expression]").forEach(btn=>btn.onclick=()=>{const label=btn.querySelector("small").textContent;document.querySelector("#poSpeech").innerHTML="Po is "+label+"! 💜<small>¡Po está "+label.toLowerCase()+"!</small>";document.querySelectorAll(".po-expression").forEach(el=>el.classList.toggle("active",el===btn))});document.querySelectorAll("[data-outfit]").forEach(btn=>btn.onclick=()=>{const id=btn.dataset.outfit;if(id!=="none"&&!d.inventory[id]){notify("Unlock this accessory in Po’s Shop first. / Desbloquéalo primero en la tienda.");return}d.accessory=id;poSave(d);poRoom()});document.querySelector("#poSaveProfile").onclick=()=>{const n=document.querySelector("#poName").value.trim().slice(0,24)||"Po";d.name=n;d.gender=document.querySelector("#poGender").value;d.fur=document.querySelector("#poFur").value;d.eyes=document.querySelector("#poEyes").value;poSave(d);poRoom();document.querySelector("#poNotice").textContent="Saved! / ¡Guardado!"};document.querySelector("#poPet").onclick=()=>{document.querySelector("#poSpeech").innerHTML="Purr... You're my favorite! 💜<small>¡Eres mi persona favorita!</small>"};document.querySelector("#poTalk").onclick=()=>{const msg="Hi! I'm "+d.name+". Let's practice English together!";document.querySelector("#poSpeech").textContent=msg;if("speechSynthesis"in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(msg);u.lang="en-US";u.rate=.88;speechSynthesis.speak(u)}};document.querySelectorAll("[data-buy]").forEach(btn=>btn.onclick=()=>{const x=PO_ITEMS.find(v=>v.id===btn.dataset.buy);if(d.coins<x.price){notify("Not enough coins yet. Complete a lesson! / ¡Necesitas más monedas!");return}d.coins-=x.price;d.inventory[x.id]=(d.inventory[x.id]||0)+1;if(x.id==="bow"||x.id==="ball")d.accessory=x.id;poSave(d);poRoom();document.querySelector("#poNotice").textContent="Purchased "+x.name+"! 💜"});document.querySelectorAll("[data-feed]").forEach(btn=>btn.onclick=()=>{const id=btn.dataset.feed;if(!d.inventory[id]){notify("You need to buy this food first. / Primero compra esta comida.");return}d.inventory[id]--;d.fed++;poSave(d);poRoom();document.querySelector("#poSpeech").innerHTML="Yummy! Thank you! 😻<small>¡Qué rico! ¡Gracias!</small>"})}

function home(){app.innerHTML=`<a class="po-home-link" href="#po"><img src="po-cat.svg" alt="Po the cat"/><span><b>🐾 Meet Po · Tu compañero de inglés</b><small>Earn coins, feed your cat & make it yours →</small></span></a>${hero("Learn English • Fly Higher ✈️","Build your English from A1 to C2, plus a separate Aviation English mode.")}<div class="grid">${["A1","A2","B1","B2","C1","C2"].map((x,i)=>i?card(x,"Coming next","locked"):card(x,"Beginner","a1")).join("")}${card("✈️ Aviation Mode","English for pilots","aviation")}${card("📚 Stories Library","Read & listen by level","stories")}</div>`}
const sections=[["📘 Grammar","grammar"],["🧠 Vocabulary","vocabulary"],["🗣️ Speaking","Speaking"],["🎧 Listening","Listening"],["📖 Reading","Reading"],["✍️ Writing","Writing"],["🔊 Pronunciation","Pronunciation"],["🧩 Use of English","Use of English"],["🏆 Final Review","Final Review"]];
function a1(){app.innerHTML=`${back("home","Levels")}${hero("🌱 A1 — Beginner","Choose a section. All A1 areas are organized separately so levels never mix.")}<div class="grid">${sections.map(x=>card(x[0],"A1",x[1].toLowerCase().replaceAll(" ","-"))).join("")}</div>`}
function blocks(kind){const d=DATA[kind]; app.innerHTML=`${back("a1","A1")}${hero(kind==="grammar"?"📘 Grammar":"🧠 Vocabulary","Choose a block.")}<div class="grid">${Object.keys(d).map((x,i)=>card(x,d[x].length+" lessons",kind+"-block-"+i)).join("")}</div>`}
function block(kind,i){const d=DATA[kind],name=Object.keys(d)[i],ls=d[name]; app.innerHTML=`${back(kind,kind==="grammar"?"Grammar":"Vocabulary")}${hero(esc(name),"Choose a lesson.")}<div class="grid">${ls.map((x,j)=>card(x,"Lesson",`lesson-${kind}-${i}-${j}`)).join("")}</div>`}
function topics(name){const list=DATA.topics[name];app.innerHTML=`${back("a1","A1")}${hero((name==="Reading"?"📖 ":name==="Listening"?"🎧 ":name==="Speaking"?"🗣️ ":"")+esc(name),name==="Reading"?"Lecturas A1: signs, messages, emails, stories, instructions and travel information.":"Choose a topic.")}<div class="grid">${list.map((x,i)=>card(x,"A1",`topic-${encodeURIComponent(name)}-${i}`)).join("")}</div>`}
const BABY_GUIDES={"Subject Pronouns":{"intro":"A subject pronoun is a small word that tells us WHO we are talking about.","es":"Un pronombre personal es una palabra pequeña que indica DE QUIÉN hablamos.","steps":[["I","yo","I am happy.","Yo estoy feliz."],["You","tú / ustedes","You are ready.","Tú estás listo/a."],["He","él","He is a pilot.","Él es piloto."],["She","ella","She is a teacher.","Ella es profesora."],["It","eso / ello","It is a plane.","Es un avión."],["We","nosotros/as","We are friends.","Somos amigos."],["They","ellos/as","They are students.","Ellos son estudiantes."]],"tip":"Use HE for a man or boy, SHE for a woman or girl, and IT for a thing or animal when you are not specifying its sex."},"Verb to be: am / is / are":{"intro":"The verb TO BE helps us say who someone is or how someone feels.","es":"TO BE significa SER o ESTAR. No usamos la misma forma con todos los pronombres.","steps":[["I am","yo soy / estoy","I am tired.","Estoy cansado/a."],["You are","tú eres / estás","You are kind.","Eres amable."],["He is","él es / está","He is a doctor.","Él es médico."],["She is","ella es / está","She is happy.","Ella está feliz."],["It is","eso es / está","It is cold.","Hace frío."],["We are","nosotros somos / estamos","We are ready.","Estamos listos."],["They are","ellos son / están","They are here.","Ellos están aquí."]],"tip":"Remember: only I uses AM. HE, SHE and IT use IS. YOU, WE and THEY use ARE."},"Possessive Adjectives":{"intro":"These words tell us who owns something.","es":"Estas palabras indican a quién le pertenece algo. Siempre van antes de una cosa o persona.","steps":[["my","mi","My book.","Mi libro."],["your","tu","Your bag.","Tu bolso."],["his","su (de él)","His car.","Su auto."],["her","su (de ella)","Her name.","Su nombre."],["our","nuestro/a","Our house.","Nuestra casa."],["their","su (de ellos)","Their school.","Su escuela."]],"tip":"Say MY BOOK, not BOOK MY. The possessive goes before the noun."},"Articles: a / an":{"intro":"A and AN are small words used before one countable thing.","es":"A y AN se usan antes de una sola cosa contable. Elige según el sonido que viene después.","steps":[["a","un / una","A pilot.","Un piloto."],["an","un / una","An airplane.","Un avión."],["a","sonido consonante","A university.","Una universidad."],["an","sonido vocal","An hour.","Una hora."]],"tip":"Listen to the SOUND, not just the first letter."},"Singular and Plural Nouns":{"intro":"One thing is singular. Two or more things are plural.","es":"Singular = una cosa. Plural = dos o más. Normalmente añadimos -s o -es.","steps":[["book → books","libro → libros","Two books.","Dos libros."],["bus → buses","autobús → autobuses","Three buses.","Tres autobuses."],["child → children","niño → niños","Two children.","Dos niños."]],"tip":"Some words change completely, like child → children."},"Demonstratives":{"intro":"These words help us point to things near or far.","es":"Los demostrativos sirven para señalar cosas cercanas o lejanas.","steps":[["This","esto / este (cerca, uno)","This is my bag.","Esta es mi bolsa."],["These","estos/as (cerca, varios)","These are my books.","Estos son mis libros."],["That","eso / aquel (lejos, uno)","That is a car.","Ese es un auto."],["Those","esos/as (lejos, varios)","Those are birds.","Esos son pájaros."]],"tip":"THIS and THAT are singular. THESE and THOSE are plural."},"Basic Adjective Position":{"intro":"Adjectives describe people and things.","es":"Los adjetivos describen cómo es algo o alguien. En inglés suelen ir ANTES del sustantivo.","steps":[["a blue car","un auto azul","It is a blue car.","Es un auto azul."],["a small house","una casa pequeña","I have a small house.","Tengo una casa pequeña."],["is happy","está feliz","She is happy.","Ella está feliz."]],"tip":"Say a RED car, not a car RED."},"Possessive 's":{"intro":"Add 's to a person's name to show that something belongs to them.","es":"Agrega 's después del nombre de alguien para decir que algo le pertenece.","steps":[["Ana's book","el libro de Ana","This is Ana's book.","Este es el libro de Ana."],["Tom's bag","el bolso de Tom","Tom's bag is blue.","El bolso de Tom es azul."],["the pilot's seat","el asiento del piloto","This is the pilot's seat.","Este es el asiento del piloto."]],"tip":"Ana's book means the book belongs to Ana."}};
const RICH_LESSONS={"Subject Pronouns":{"definition":"Subject pronouns tell us WHO does the action. They replace a person's name or a thing.","translation":"Los pronombres personales indican quién realiza la acción y reemplazan un nombre.","simple":"Ana is my friend → SHE is my friend. Carlos and I are students → WE are students.","examples":[["I am a student.","Yo soy estudiante."],["You are my friend.","Tú eres mi amigo/a."],["He is a pilot.","Él es piloto."],["She is a teacher.","Ella es profesora."],["It is an airplane.","Es un avión."],["We are ready.","Nosotros estamos listos."],["They are at the airport.","Ellos están en el aeropuerto."]],"question":{"prompt":"___ is my brother.","choices":["She","He","They"],"answer":1,"explain":"Brother refers to a male person, so use HE."},"review":"I = yo · You = tú/ustedes · He = él · She = ella · It = eso/ello · We = nosotros · They = ellos/ellas."},"Verb to be: am / is / are":{"definition":"Use AM, IS or ARE to say who someone is, what something is, or how someone feels.","translation":"El verbo to be significa ser o estar. Su forma cambia según el sujeto.","simple":"I → AM. He / She / It → IS. You / We / They → ARE.","examples":[["I am happy.","Estoy feliz."],["You are a student.","Eres estudiante."],["He is tired.","Él está cansado."],["She is at home.","Ella está en casa."],["It is cold.","Hace frío."],["We are friends.","Somos amigos."],["They are pilots.","Ellos son pilotos."]],"question":{"prompt":"She ___ a pilot.","choices":["am","is","are"],"answer":1,"explain":"Use IS with she, he and it."},"review":"I am · You are · He is · She is · It is · We are · They are."},"Possessive Adjectives":{"definition":"Possessive adjectives show who something belongs to. Put them before a noun.","translation":"Los adjetivos posesivos indican de quién es algo y van antes del sustantivo.","simple":"I → my; you → your; he → his; she → her; it → its; we → our; they → their.","examples":[["My name is Alex.","Mi nombre es Alex."],["Your bag is blue.","Tu bolso es azul."],["His car is new.","Su auto es nuevo (de él)."],["Her book is here.","Su libro está aquí (de ella)."],["Our school is big.","Nuestra escuela es grande."]],"question":{"prompt":"I have a book. It is ___ book.","choices":["my","his","their"],"answer":0,"explain":"Use MY for something belonging to I."},"review":"my, your, his, her, its, our, their + noun."},"Articles: a / an":{"definition":"Use A before a consonant sound and AN before a vowel sound with singular countable nouns.","translation":"Usa a o an para hablar de un sustantivo contable singular. Depende del sonido inicial.","simple":"A pilot. AN airplane. A university (starts with a /y/ sound).","examples":[["I am a student.","Soy estudiante."],["It is an apple.","Es una manzana."],["She is a pilot.","Ella es piloto."],["This is an airport.","Este es un aeropuerto."]],"question":{"prompt":"This is ___ airplane.","choices":["a","an","the"],"answer":1,"explain":"Airplane begins with a vowel sound, so use AN."},"review":"A + consonant sound; AN + vowel sound."},"Singular and Plural Nouns":{"definition":"Singular means one. Plural means more than one. Most nouns add -s or -es.","translation":"Singular significa uno; plural significa más de uno.","simple":"one book → two books; one box → two boxes; one child → two children.","examples":[["One plane, two planes.","Un avión, dos aviones."],["One bus, three buses.","Un autobús, tres autobuses."],["One child, two children.","Un niño, dos niños."]],"question":{"prompt":"Two ___ are outside.","choices":["bus","buses","buss"],"answer":1,"explain":"Bus takes -es in the plural: buses."},"review":"Most plurals add -s; some add -es; others are irregular."},"Demonstratives":{"definition":"Use THIS and THESE for things near you; THAT and THOSE for things farther away.","translation":"This/these indican cercanía; that/those indican distancia.","simple":"THIS = one near. THESE = many near. THAT = one far. THOSE = many far.","examples":[["This is my bag.","Esta es mi bolsa."],["These are my keys.","Estas son mis llaves."],["That is an airplane.","Ese es un avión."],["Those are my friends.","Esos son mis amigos."]],"question":{"prompt":"___ are my books here.","choices":["This","These","That"],"answer":1,"explain":"Books is plural and here suggests near: THESE."},"review":"this/that = singular; these/those = plural."},"Basic Adjective Position":{"definition":"In English, adjectives usually come before a noun, or after the verb be.","translation":"En inglés, el adjetivo suele ir antes del sustantivo o después de be.","simple":"A red car. The car is red.","examples":[["It is a big airplane.","Es un avión grande."],["The airplane is big.","El avión es grande."],["She has a blue bag.","Ella tiene un bolso azul."]],"question":{"prompt":"Choose the correct phrase.","choices":["a car red","a red car","red a car"],"answer":1,"explain":"An adjective usually goes before its noun."},"review":"adjective + noun; subject + be + adjective."},"Possessive 's":{"definition":"Add 's to a person's name to show possession.","translation":"Añade 's al nombre de una persona para indicar pertenencia.","simple":"Ana's book = the book belongs to Ana.","examples":[["This is Maria's bag.","Este es el bolso de María."],["That is the pilot's seat.","Ese es el asiento del piloto."],["Tom's car is red.","El auto de Tom es rojo."]],"question":{"prompt":"The book belongs to Anna. It is ___ book.","choices":["Anna","Annas","Anna's"],"answer":2,"explain":"Use 's to show possession."},"review":"person's name + 's + thing."}};

const READING_LESSONS={"Signs":{"en":"At the airport, Emma sees three signs: EXIT, NO SMOKING and GATE 4. She follows the EXIT sign to leave the building.","es":"En el aeropuerto, Emma ve tres letreros: SALIDA, PROHIBIDO FUMAR y PUERTA 4. Sigue el letrero de SALIDA para salir del edificio.","q":"Which sign shows the way out?","choices":["EXIT","GATE 4","NO SMOKING"],"answer":0},"Notices":{"en":"NOTICE: The library closes at 5 p.m. on Friday. Please return your books before closing time.","es":"AVISO: La biblioteca cierra a las 5 p. m. el viernes. Devuelve tus libros antes del cierre.","q":"When does the library close?","choices":["At 5 p.m.","At 8 a.m.","At 7 p.m."],"answer":0},"Posters":{"en":"ENGLISH CLUB! Join us on Saturday at 10 a.m. in Room 3. Everyone is welcome. Bring a notebook!","es":"¡CLUB DE INGLÉS! Únete el sábado a las 10 a. m. en el aula 3. Todos son bienvenidos. ¡Trae un cuaderno!","q":"What should you bring?","choices":["A suitcase","A notebook","A bicycle"],"answer":1},"Menus":{"en":"CAFÉ MENU: Tea $2. Coffee $3. Sandwich $5. Orange juice $4. Mia buys a sandwich and a tea.","es":"MENÚ: Té $2. Café $3. Sándwich $5. Jugo de naranja $4. Mia compra un sándwich y un té.","q":"How much does Mia pay?","choices":["$5","$7","$9"],"answer":1},"Timetables":{"en":"BUS TIMES: City Center 8:00, Airport 8:30, Museum 9:00. The airport bus leaves at half past eight.","es":"HORARIOS: Centro 8:00, Aeropuerto 8:30, Museo 9:00. El autobús al aeropuerto sale a las ocho y media.","q":"When does the airport bus leave?","choices":["8:00","8:30","9:00"],"answer":1},"Forms":{"en":"Name: Alex. Surname: Rivera. Country: Bolivia. Age: 19. Email: alex@example.com.","es":"Nombre: Alex. Apellido: Rivera. País: Bolivia. Edad: 19. Correo: alex@example.com.","q":"Where is Alex from?","choices":["Brazil","Bolivia","Peru"],"answer":1},"Ads":{"en":"FOR SALE: Blue bicycle. Good condition. Price: $80. Call after 6 p.m.","es":"EN VENTA: Bicicleta azul. Buen estado. Precio: $80. Llamar después de las 6 p. m.","q":"What is for sale?","choices":["A bicycle","A phone","A car"],"answer":0},"Text Messages":{"en":"Hi Leo! I am at the park. Can you come at four? — Sam. Hi Sam! Yes, see you there! — Leo.","es":"¡Hola, Leo! Estoy en el parque. ¿Puedes venir a las cuatro? — Sam. ¡Hola, Sam! Sí, ¡nos vemos allí! — Leo.","q":"Where is Sam?","choices":["At school","At the park","At home"],"answer":1},"Short Emails":{"en":"Dear Anna, I arrive in London on Monday at 2 p.m. Can we meet at the station? Best, Tom.","es":"Querida Anna: Llego a Londres el lunes a las 2 p. m. ¿Podemos encontrarnos en la estación? Saludos, Tom.","q":"When does Tom arrive?","choices":["Monday","Tuesday","Friday"],"answer":0},"Personal Profiles":{"en":"My name is Sofia. I am 22 years old. I live in Cochabamba. I like music and books.","es":"Me llamo Sofía. Tengo 22 años. Vivo en Cochabamba. Me gustan la música y los libros.","q":"Where does Sofia live?","choices":["La Paz","Cochabamba","Santa Cruz"],"answer":1},"Simple Descriptions":{"en":"My bedroom is small and bright. There is a bed, a desk and a blue chair. I study at my desk.","es":"Mi dormitorio es pequeño y luminoso. Hay una cama, un escritorio y una silla azul. Estudio en mi escritorio.","q":"What color is the chair?","choices":["Red","Blue","Green"],"answer":1},"Short Stories":{"en":"On Sunday, Ben gets up early. He eats breakfast and walks to the park. He meets his friend Lily. They play football and go home happy.","es":"El domingo, Ben se levanta temprano. Desayuna y camina al parque. Se encuentra con su amiga Lily. Juegan fútbol y vuelven felices a casa.","q":"Who does Ben meet?","choices":["Lily","Emma","Tom"],"answer":0},"Basic Instructions":{"en":"To make tea: First, boil water. Next, put a tea bag in a cup. Add hot water. Wait three minutes.","es":"Para preparar té: Primero, hierve agua. Después, coloca una bolsita de té en una taza. Añade agua caliente. Espera tres minutos.","q":"What do you do first?","choices":["Add sugar","Boil water","Drink tea"],"answer":1},"Simple Travel Information":{"en":"FLIGHT AB123: Destination Lima. Departure 10:45 a.m. Gate 6. Please arrive at the gate early.","es":"VUELO AB123: Destino Lima. Salida 10:45 a. m. Puerta 6. Llega temprano a la puerta.","q":"What is the destination?","choices":["Lima","Quito","Bogotá"],"answer":0},"A1 Reading Review":{"en":"Nina is at the airport. Her flight to Cusco leaves at 11:20 from Gate 2. She buys water for $2 and waits near the gate.","es":"Nina está en el aeropuerto. Su vuelo a Cusco sale a las 11:20 desde la puerta 2. Compra agua por $2 y espera cerca de la puerta.","q":"Which gate does Nina need?","choices":["Gate 1","Gate 2","Gate 3"],"answer":1}};
const GLOSSARY={"improve":"mejorar","subject":"sujeto","pronoun":"pronombre","pronouns":"pronombres","replace":"reemplazar","sentence":"oración","sentences":"oraciones","student":"estudiante","pilot":"piloto","airport":"aeropuerto","airplane":"avión","friend":"amigo/a","friends":"amigos","happy":"feliz","tired":"cansado","ready":"listo/a","learn":"aprender","practice":"practicar","review":"repasar","examples":"ejemplos","example":"ejemplo","question":"pregunta","answer":"respuesta","correct":"correcto","wrong":"incorrecto","book":"libro","books":"libros","teacher":"profesor/a","family":"familia","house":"casa","home":"hogar","school":"escuela","work":"trabajo","weather":"clima","flight":"vuelo","gate":"puerta de embarque","departure":"salida","arrival":"llegada","destination":"destino","sign":"letrero","signs":"letreros","exit":"salida","leave":"salir","building":"edificio","closes":"cierra","before":"antes","after":"después","bring":"traer","notebook":"cuaderno","sandwich":"sándwich","tea":"té","coffee":"café","price":"precio","times":"horarios","early":"temprano","walk":"caminar","park":"parque","meet":"encontrarse","station":"estación","bright":"luminoso","small":"pequeño","chair":"silla","desk":"escritorio","water":"agua","wait":"esperar","first":"primero","next":"después","boil":"hervir","cup":"taza","name":"nombre","surname":"apellido","country":"país","age":"edad","buy":"comprar","buys":"compra","speak":"hablar","listen":"escuchar","read":"leer","write":"escribir","you":"tú/ustedes","she":"ella","he":"él","they":"ellos/ellas","we":"nosotros","it":"eso/ello","my":"mi","your":"tu","his":"su (de él)","her":"su (de ella)","our":"nuestro","their":"su (de ellos)"};
function explainWords(html){return html.replace(/>([^<>]+)</g,(full,t)=>">"+t.replace(/\b[A-Za-z]+(?:'[A-Za-z]+)?\b/g,w=>{const k=w.toLowerCase();return GLOSSARY[k]?`<button class="word-help" data-word="${k}" title="Ver significado de ${w}">${w}</button>`:w})+"<")}
function setupWordHelp(){document.querySelectorAll(".word-help").forEach(btn=>btn.onclick=()=>{const w=btn.dataset.word;const el=document.querySelector("#dictionaryToast");el.innerHTML=`<b>${esc(w)}</b><span>${esc(GLOSSARY[w])}</span><button aria-label="Cerrar" id="closeDictionary">×</button>`;el.hidden=false;document.querySelector("#closeDictionary").onclick=()=>el.hidden=true})}
const lessonInfo={
"Subject Pronouns":["I, you, he, she, it, we and they replace the subject of a sentence.",["I am a student.","She is my friend.","They are at home."]],
"Verb to be: am / is / are":["Use am with I, is with he/she/it, and are with you/we/they.",["I am ready.","He is a pilot.","We are students."]],
"Signs":["Read short public signs and identify their simple meaning.",["NO ENTRY = Do not enter.","EXIT = Way out.","OPEN = The place is operating."]],
"Simple Travel Information":["Understand simple times, destinations, gates and travel instructions.",["Flight at 8:30.","Gate 4.","Bus to the airport."]]
};
function lesson(title,crumb){
const info=lessonInfo[title]||[`Learn the essentials of ${title} with clear examples and short activities.`,[`Let's practice ${title.toLowerCase()}.`,"Read, repeat, and make your own sentence."]];
const stages=[["📖","Learn","Understand the topic","lilac"],["💡","Baby Mode","A super simple explanation","pink"],["✨","Examples","Explore real sentences","blue"],["✏️","Practice","Try short exercises","mint"],["💬","Use it","Make your own sentences","peach"],["🏆","Mini Test","Check your knowledge","violet"]];
const isVocabulary=crumb.href.startsWith("vocabulary-block-");
const activeStageIds=isVocabulary?[0,3,4]:[0,1,2,3,4,5];
const activeStages=activeStageIds.map(i=>stages[i]);
const slug=s=>s.toLowerCase().replaceAll(" ","-");
const rich=RICH_LESSONS[title];
const reading=READING_LESSONS[title];
const bilingual=rich?rich.examples.map(([en,es])=>`<div class="bilingual-example"><b>${esc(en)}</b><span>${esc(es)}</span></div>`).join(""):info[1].map(x=>`<div class="example">${esc(x)}</div>`).join("");
const quiz=(rich||reading)?`<div class="quiz-panel"><p><b>${esc((rich?.question.prompt||reading?.q))}</b></p>${(rich?.question.choices||reading?.choices).map((x,i)=>`<button class="quiz-option" data-answer="${i}">${esc(x)}</button>`).join("")}<p id="quizFeedback" aria-live="polite"></p></div>`:`<p>Write an example without looking at the lesson.</p>`;
const guide=BABY_GUIDES[title];
const babyEnglish=rich?.simple||info[0];
const babyCards=guide?`<div class="baby-intro"><span>🧸 Step 1 · The idea</span><p><b>🇬🇧 ${esc(guide.intro)}</b></p><p>🇪🇸 ${esc(guide.es)}</p></div><h3>🧩 Step 2 · Learn one by one</h3><div class="baby-tiles">${guide.steps.map(([en,es,example,translation])=>`<div class="baby-tile"><strong>${esc(en)}</strong><span>${esc(es)}</span><p>${esc(example)}</p><small>${esc(translation)}</small></div>`).join("")}</div><div class="baby-tip">💡 <b>Remember / Recuerda</b><p>${esc(guide.tip)}</p></div>`:`<div class="baby-intro"><b>🇬🇧 ${esc(babyEnglish)}</b><p>🇪🇸 ${esc(rich?.translation||"Vamos a aprender con ejemplos fáciles y paso a paso.")}</p></div>`;
const babySpanish=rich?.translation||reading?.es||"Lee el ejemplo con calma y reconoce las palabras importantes.";
const story=reading?`<div class="reading-story"><div class="reading-icon">📚 ✈️</div><p>${esc(reading.en)}</p><button class="back" id="showTranslation">🇪🇸 Mostrar traducción</button><p class="story-translation" hidden>${esc(reading.es)}</p></div>`:"";
const learnTiles=guide?guide.steps.map(([form,meaning,example,translation],i)=>`<div class="learn-tile"><div class="learn-tile-top"><span class="learn-tile-number">${String(i+1).padStart(2,"0")}</span><strong>${esc(form)}</strong></div><span class="learn-tile-meaning">${esc(meaning)}</span><div class="learn-tile-example">${esc(example)}</div><small>${esc(translation)}</small></div>`).join(""):"";
const learnContent=guide?`<div class="learn-intro"><span class="learn-eyebrow">📖 LEARN · A1 GRAMMAR</span><h2>${esc(title)}</h2><p>${esc(guide.intro)}</p><p class="learn-intro-es">🇪🇸 ${esc(guide.es)}</p></div><div class="learn-section-title"><h3>🧩 Learn the patterns</h3><span>English → Español</span></div><div class="learn-tiles">${learnTiles}</div><div class="learn-reminder"><b>💡 Remember / Recuerda</b><p>${esc(guide.tip)}</p></div>`:`<div class="learn-intro"><span class="learn-eyebrow">📖 LEARN</span><h2>${esc(title)}</h2><p>${esc(rich?.definition||info[0])}</p>${rich?`<p class="learn-intro-es">🇪🇸 ${esc(rich.translation)}</p>`:""}</div><div class="learn-section-title"><h3>✨ Examples / Ejemplos</h3></div><div class="learn-tiles">${rich?rich.examples.map(([en,es])=>`<div class="learn-tile"><div class="learn-tile-example">${esc(en)}</div><small>${esc(es)}</small></div>`).join(""):bilingual}</div>`;
const content=[
`${reading?`<h2>📖 Learn</h2>${story}`:learnContent}`,
`<h2>💡 Baby Mode · Step by step</h2><p>Simple English + español, one idea at a time.</p>${babyCards}`,
`<h2>✨ Examples</h2><p>Read in English, then compare with Spanish.</p>${story||bilingual}`,
`<h2>✏️ Practice</h2><p>Choose the correct answer. You will see feedback immediately.</p>${quiz}`,
`<h2>💬 Use it</h2><p>Write two sentences about your life using this topic.</p><textarea id="ownSentence" rows="4" placeholder="Example: I am a student…"></textarea><p class="small-help">Your writing stays on this page; it is not automatically graded.</p>`,
`<h2>🏆 Mini Test</h2><p>Try the question again without looking at the examples.</p>${quiz}`
];
const key="englishapp:"+title;
const saved=(()=>{try{return JSON.parse(localStorage.getItem(key)||"[]")}catch{return []}})();
const done=new Set(saved);
const renderStage=i=>{
document.querySelector("#lessonOverview").hidden=true;
document.querySelector("#stageScreen").hidden=false;
document.querySelector("#stageHeading").textContent=stages[i][0]+" "+stages[i][1];
document.querySelector("#stagePosition").textContent=(activeStageIds.indexOf(i)+1)+" / "+activeStages.length;
document.querySelector("#stageContent").innerHTML=content[i]+`<div class="lesson-actions"><button class="back" id="markDone">✓ Mark complete</button><button class="back" id="nextStage">${i===activeStageIds[activeStageIds.length-1]?"Finish lesson":"Next →"}</button></div>`;
document.querySelectorAll(".study-card").forEach(el=>el.classList.toggle("selected",i===Number(el.dataset.stage)));
document.querySelectorAll(".quiz-option").forEach(btn=>btn.onclick=()=>{const ok=Number(btn.dataset.answer)===(rich?.question.answer??reading?.answer);const feedback=document.querySelector("#quizFeedback");feedback.textContent=ok?"✓ Correct! "+(rich?.question.explain||"Well done! / ¡Bien hecho!"):"Try again. / Inténtalo otra vez.";feedback.className=ok?"correct":"incorrect"});
const show=document.querySelector("#showTranslation");if(show)show.onclick=()=>{const tr=document.querySelector(".story-translation");tr.hidden=!tr.hidden;show.textContent=tr.hidden?"🇪🇸 Mostrar traducción":"Ocultar traducción"};
const detail=document.querySelector("#stageContent");detail.querySelectorAll(".reading-story p:not(.story-translation),.bilingual-example b,.simple-rule,.learn-tile-example,.learn-intro>p:not(.learn-intro-es)").forEach(el=>{el.innerHTML=explainWords(el.innerHTML)});setupWordHelp();
document.querySelector("#markDone").onclick=()=>{done.add(i);try{localStorage.setItem(key,JSON.stringify([...done]))}catch{}updateProgress();const awarded=activeStageIds.every(n=>done.has(n))&&poAward(key);renderStage(i);if(awarded){const msg=document.createElement("div");msg.className="po-earned";msg.innerHTML="🐱 Lesson complete! +50 🪙 <a href=\"#po\">Visit your cat →</a>";document.querySelector("#stageContent").prepend(msg)}};
document.querySelector("#nextStage").onclick=()=>{if(i===activeStageIds[activeStageIds.length-1]){showOverview();return}renderStage(activeStageIds[activeStageIds.indexOf(i)+1]);window.scrollTo({top:0,behavior:"smooth"})};
};
const showOverview=()=>{document.querySelector("#lessonOverview").hidden=false;document.querySelector("#stageScreen").hidden=true;window.scrollTo({top:0,behavior:"smooth"})};
const updateProgress=()=>{document.querySelector("#lessonCount").textContent=activeStageIds.filter(n=>done.has(n)).length+" / "+activeStages.length+" completed";document.querySelector("#lessonFill").style.width=(activeStageIds.filter(n=>done.has(n)).length/activeStages.length*100)+"%";document.querySelectorAll(".study-card").forEach(el=>el.classList.toggle("completed",done.has(Number(el.dataset.stage))))};
app.innerHTML=`${back(crumb.href,esc(crumb.label))}<div class="study-layout" id="studyLayout"><aside class="study-sidebar" id="studySidebar"><h3>✨ A1 English</h3>${sections.map(x=>`<a href="#${x[1].toLowerCase().replaceAll(" ","-")}">${x[0]}</a>`).join("")}<a href="#aviation">✈️ Aviation Mode →</a></aside><div class="study-main"><div class="study-toolbar"><button class="sidebar-toggle" id="sidebarToggle" aria-controls="studySidebar" aria-expanded="true">☰ <span id="sidebarToggleLabel">Hide menu</span></button><span class="study-toolbar-label">✨ Your learning space</span></div><div id="lessonOverview"><div class="study-breadcrumb">A1 › ${isVocabulary?"Vocabulary":"Grammar"} › ${esc(title)}</div><section class="study-hero"><div><span class="study-label">A1 &nbsp; • &nbsp; Your lesson</span><h1>${esc(title)}</h1><p>${esc(info[0])}</p></div><div class="study-art">📒<span>✦</span><small>Small steps,<br>big progress!</small></div></section><div class="study-progress"><b>Lesson Progress</b><span id="lessonCount">0 / ${activeStages.length} completed</span><div class="progress-track"><div id="lessonFill"></div></div></div><div class="study-grid">${activeStages.map((s,i)=>`<button class="study-card ${s[3]}" data-stage="${activeStageIds[i]}"><span class="study-num">${i+1}</span><span class="study-emoji">${s[0]}</span><strong>${s[1]}</strong><small>${s[2]}</small><span class="study-arrow">→</span></button>`).join("")}</div></div><div id="stageScreen" hidden><div class="stage-topbar"><button class="back" id="stageBack">← All steps</button><span id="stagePosition">1 / 6</span></div><h2 id="stageHeading"></h2><section class="study-detail" id="stageContent"></section></div><div class="dictionary-toast" id="dictionaryToast" hidden></div></div></div>`;
document.querySelectorAll(".study-card").forEach(el=>el.onclick=()=>{renderStage(Number(el.dataset.stage));window.scrollTo({top:0,behavior:"smooth"})});document.querySelector("#stageBack").onclick=showOverview;const layout=document.querySelector("#studyLayout");const toggle=document.querySelector("#sidebarToggle");const collapsed=(()=>{try{return localStorage.getItem("englishapp:sidebarHidden")==="yes"}catch{return false}})();const setSidebar=hidden=>{layout.classList.toggle("sidebar-collapsed",hidden);toggle.setAttribute("aria-expanded",String(!hidden));document.querySelector("#sidebarToggleLabel").textContent=hidden?"Show menu":"Hide menu";};setSidebar(collapsed);toggle.onclick=()=>{const hidden=!layout.classList.contains("sidebar-collapsed");setSidebar(hidden);try{localStorage.setItem("englishapp:sidebarHidden",hidden?"yes":"no")}catch{}};updateProgress();showOverview();
}

const STORY_LIBRARY={"A1":[{"title":"The Little Bird and the Storm","icon":"🐦","moral":"Small acts of kindness can make a big difference.","paras":["A little bird lives in a big tree. Every morning, she sings to the animals in the forest.","One day, dark clouds cover the sky. The wind is strong. A small rabbit cannot find his home.","The bird sees the rabbit. She flies down and says, “Come with me. You can stay in my tree.”","The storm ends in the morning. The rabbit smiles and says, “Thank you, little bird.”","The bird is small, but her heart is big."]},{"title":"The Fox and the Grapes","icon":"🦊","moral":"It is easy to dislike something when we cannot have it.","paras":["A hungry fox walks through a garden. He sees some beautiful grapes high on a vine.","“Those grapes look delicious!” he says. He jumps, but he cannot reach them.","He jumps again and again. The grapes are still too high.","At last, the fox walks away. “I do not want those grapes. They are probably sour,” he says.","But the grapes are not the problem. The fox simply cannot reach them."]},{"title":"The Honest Woodcutter","icon":"🪓","moral":"Honesty is more valuable than gold.","paras":["A poor woodcutter works near a river. One day, his old axe falls into the water.","He is sad because he needs the axe for his work.","A kind woman appears. She shows him a gold axe. “Is this yours?” she asks.","“No,” says the man. She shows him a silver axe. “No,” he says again.","Finally, she shows him his old axe. “Yes! That is mine!” he says.","The woman smiles. Because he is honest, she gives him all three axes."]},{"title":"The Ant and the Dove","icon":"🐜","moral":"Kindness often comes back to us.","paras":["An ant falls into a river. The water is fast, and the ant is afraid.","A dove sees the ant. She drops a leaf into the water.","The ant climbs onto the leaf and reaches the land. “Thank you!” she says.","Later, a man wants to catch the dove. The ant sees him and bites his foot.","The man shouts, and the dove flies away. The two small friends help each other."]},{"title":"The Lion and the Mouse","icon":"🦁","moral":"Even someone small can help someone strong.","paras":["A lion sleeps under a tree. A little mouse runs over his paw.","The lion wakes up and catches the mouse. “Please let me go,” says the mouse. “One day I can help you.”","The lion laughs, but he lets the mouse go.","A few days later, the lion is caught in a net. He cannot get out.","The mouse hears him and runs to help. She bites the ropes until the lion is free.","“Thank you,” says the lion. “You are a very good friend.”"]}],"A2":[{"title":"The Two Seeds","icon":"🌱","moral":"Growth requires courage.","paras":["Two seeds rested in the soil of a quiet garden. The first seed dreamed of sunlight, rain, and tall green leaves.","“I want to grow,” she said. She pushed her roots down and her small stem up.","The second seed was afraid. “What if the rain is too strong? What if an animal eats me?”","She decided to wait until everything was safe.","Weeks passed. The first seed became a beautiful flower. The second seed stayed hidden under the ground.","One morning, a hungry bird found the second seed and ate it.","The flower looked at the sky and understood that taking a small risk had helped her live."]},{"title":"The Empty Pot","icon":"🪴","moral":"Truth matters more than pretending to succeed.","paras":["A king wanted to choose a new leader. He gave every child in the village one seed.","“Grow this seed and bring me your plant in three months,” he said.","A boy named Leo watered his seed every day, but nothing grew. He tried different soil and more sunlight.","On the final day, the other children carried beautiful plants. Leo brought only an empty pot.","The king smiled when he saw Leo. “I boiled every seed before giving it to you,” he explained. “None could grow.”","Leo was the only child who had told the truth. The king chose him."]}]};
const STORY_WORDS={"bird":"pájaro","little":"pequeño/a","storm":"tormenta","tree":"árbol","morning":"mañana","sings":"canta","animals":"animales","forest":"bosque","clouds":"nubes","sky":"cielo","wind":"viento","strong":"fuerte","rabbit":"conejo","flies":"vuela","stay":"quedarse","ends":"termina","smiles":"sonríe","heart":"corazón","fox":"zorro","grapes":"uvas","hungry":"hambriento","garden":"jardín","beautiful":"hermoso/a","vine":"vid","delicious":"delicioso","jumps":"salta","reach":"alcanzar","high":"alto","away":"lejos","sour":"agrio","woodcutter":"leñador","river":"río","axe":"hacha","falls":"cae","sad":"triste","kind":"amable","gold":"oro","silver":"plata","honest":"honesto","honesty":"honestidad","dove":"paloma","ant":"hormiga","water":"agua","leaf":"hoja","climbs":"sube","land":"tierra","catch":"atrapar","bites":"muerde","foot":"pie","lion":"león","mouse":"ratón","sleeps":"duerme","paw":"pata","laughs":"ríe","net":"red","ropes":"cuerdas","free":"libre","seeds":"semillas","soil":"tierra","sunlight":"luz solar","roots":"raíces","stem":"tallo","afraid":"asustado","hidden":"escondido","flower":"flor","courage":"valentía","king":"rey","leader":"líder","village":"pueblo","grow":"crecer","months":"meses","empty":"vacío","pot":"maceta","truth":"verdad","boiled":"hirvió","choose":"elegir"};
let storyUtterance=null;
function storiesHome(){stopStory();app.innerHTML=`${back("home","Home")}${hero("📚 Stories Library","Choose your level. Read stories, discover words, and listen as you read.")}<div class="story-level-grid">${["A1","A2","B1","B2","C1","C2"].map((l,i)=>`<a class="story-level" href="#stories-${l}"><span>${["🌱","🌼","🌿","🌳","✨","🏆"][i]}</span><strong>${l}</strong><small>${STORY_LIBRARY[l]?.length||0} stories ${STORY_LIBRARY[l]?"available":"coming soon"}</small></a>`).join("")}</div>`}
function storyList(level){stopStory();const list=STORY_LIBRARY[level]||[];app.innerHTML=`${back("stories","Stories Library")}${hero("📚 "+level+" Stories",list.length?"Choose a story and enjoy reading.":"Stories for this level are coming soon.")}<div class="story-list">${list.map((x,i)=>`<a class="story-list-card" href="#story-${level}-${i}"><div class="story-cover">${x.icon}</div><div><span class="pill">${level} • Story ${i+1}</span><h3>${esc(x.title)}</h3><p>Read & listen →</p></div></a>`).join("")}</div>`}
function stopStory(){if(typeof speechSynthesis!=="undefined")speechSynthesis.cancel();storyUtterance=null}
function storyPage(level,i){stopStory();const story=STORY_LIBRARY[level]?.[i];if(!story){storyList(level);return}
const lookup=w=>STORY_WORDS[w.toLowerCase()]||GLOSSARY[w.toLowerCase()];
const words=p=>p.split(/(\b[A-Za-z]+(?:'[A-Za-z]+)?\b)/g).map(w=>/^[A-Za-z]/.test(w)?`<button class="story-word" data-word="${esc(w.toLowerCase())}">${esc(w)}</button>`:esc(w)).join("");
app.innerHTML=`${back("stories-"+level,level+" Stories")}<article class="story-reader"><div class="story-reader-head"><span class="pill">${level} • Story</span><div class="story-scene">${story.icon}<span>✦</span></div><h1>${esc(story.title)}</h1><p>Tap an underlined word to see its Spanish meaning.</p><div class="story-player"><button id="storyPlay">▶ Listen</button><button id="storyPause">⏸ Pause</button><button id="storyStop">■ Stop</button><label>Voice <select id="storyVoice"><option value="">Default voice</option></select></label><label>Speed <select id="storySpeed"><option value="0.8">Slow</option><option value="1" selected>Normal</option><option value="1.15">Fast</option></select></label></div><p id="storyAudioStatus" aria-live="polite"></p></div><div class="story-pages">${story.paras.map((p,j)=>`<p class="story-paragraph" data-paragraph="${j}">${words(p)}</p>`).join("")}</div><div class="story-moral"><b>🌟 The moral of the story</b><p>${esc(story.moral)}</p></div><div class="story-dictionary" id="storyDictionary" hidden></div><div class="story-end"><a class="back" href="#stories-${level}">← All ${level} stories</a></div></article>`;
document.querySelectorAll(".story-word").forEach(el=>el.onclick=()=>{const w=el.dataset.word;const box=document.querySelector("#storyDictionary");box.hidden=false;box.innerHTML=`<span>📖 <b>${esc(w)}</b> — ${esc(lookup(w)||"Traducción pendiente")}</span><button id="storyDictionaryClose">×</button>`;document.querySelector("#storyDictionaryClose").onclick=()=>box.hidden=true});
const voiceSelect=document.querySelector("#storyVoice");
function populateVoices(){if(!("speechSynthesis" in window))return;const vs=speechSynthesis.getVoices().filter(v=>v.lang.toLowerCase().startsWith("en"));const selected=voiceSelect.value;voiceSelect.innerHTML='<option value="">Default voice</option>'+vs.map(v=>`<option value="${esc(v.voiceURI)}">${esc(v.name)} (${esc(v.lang)})</option>`).join("");if(vs.some(v=>v.voiceURI===selected))voiceSelect.value=selected;}
populateVoices();if("speechSynthesis" in window)speechSynthesis.onvoiceschanged=populateVoices;
const status=document.querySelector("#storyAudioStatus");const play=document.querySelector("#storyPlay");
play.onclick=()=>{if(!("speechSynthesis" in window)){status.textContent="Audio is not supported in this browser.";return}if(speechSynthesis.paused&&storyUtterance){speechSynthesis.resume();status.textContent="Playing…";return}stopStory();storyUtterance=new SpeechSynthesisUtterance(story.paras.join(" "));storyUtterance.lang="en-US";const chosen=speechSynthesis.getVoices().find(v=>v.voiceURI===voiceSelect.value);if(chosen)storyUtterance.voice=chosen;storyUtterance.pitch=1.08;storyUtterance.rate=Number(document.querySelector("#storySpeed").value);storyUtterance.onend=()=>{status.textContent="Finished ✓";storyUtterance=null};storyUtterance.onerror=()=>{status.textContent="Audio unavailable on this device."};speechSynthesis.speak(storyUtterance);status.textContent="Playing…"};
document.querySelector("#storyPause").onclick=()=>{if("speechSynthesis" in window){speechSynthesis.pause();status.textContent="Paused"}};
document.querySelector("#storyStop").onclick=()=>{stopStory();status.textContent="Stopped"};
}
function aviation(){app.innerHTML=`${back("home","Home")}${hero("✈️ Aviation Mode","A separate aviation-English track for pilot communication and vocabulary.")}<div class="grid">${Object.keys(DATA.aviation).map((x,i)=>card(x,DATA.aviation[x].length+" lessons","aviation-block-"+i)).join("")}</div>`}
function aviationBlock(i){let n=Object.keys(DATA.aviation)[i],ls=DATA.aviation[n];app.innerHTML=`${back("aviation","Aviation Mode")}${hero("✈️ "+esc(n),"Pilot English module")}<div class="grid">${ls.map((x,j)=>card(x,"Aviation English",`aviation-lesson-${i}-${j}`)).join("")}</div>`}

/* Po follows the learner across routes; its visual asset is replaceable independently. */
function poCompanion(){
 let root=document.querySelector("#poCompanion");
 if(!root){root=document.createElement("div");root.id="poCompanion";root.className="po-companion";root.innerHTML='<button class="po-companion-toggle" type="button" aria-label="Hide Po" title="Hide Po">×</button><button class="po-companion-pet" type="button" aria-label="Pet Po"><img src="po-cat.svg" alt="Po, your cat companion"></button><div class="po-companion-bubble" role="status" aria-live="polite"></div><button class="po-companion-show" type="button" aria-label="Show Po">🐾 Po</button>';document.body.appendChild(root);
 const bubble=root.querySelector(".po-companion-bubble");const pet=root.querySelector(".po-companion-pet");let bubbleTimer;
 const say=(english,spanish)=>{bubble.innerHTML=esc(english)+"<small>"+esc(spanish)+"</small>";bubble.classList.add("visible");clearTimeout(bubbleTimer);bubbleTimer=setTimeout(()=>bubble.classList.remove("visible"),3400)};
 pet.onclick=()=>{root.classList.remove("po-napping");root.classList.add("po-petted");setTimeout(()=>root.classList.remove("po-petted"),650);const phrases=[["Prrr... thank you! 💜","¡Gracias por acariciarme!"],["You're doing great!","¡Lo estás haciendo genial!"],["Meow! Let's learn!","¡Miau! ¡Aprendamos!"]];const p=phrases[Math.floor(Math.random()*phrases.length)];say(...p);try{const ctx=new(window.AudioContext||window.webkitAudioContext)();const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type="sine";osc.frequency.setValueAtTime(570,ctx.currentTime);osc.frequency.exponentialRampToValueAtTime(300,ctx.currentTime+.24);gain.gain.setValueAtTime(.0001,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.065,ctx.currentTime+.025);gain.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+.3);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.31);osc.onended=()=>ctx.close()}catch{}};
 // Drag Po with mouse or finger; a short tap still pets him.
 let dragState=null,ignoreClick=false;
 pet.addEventListener("pointerdown",e=>{if(e.button!==0&&e.pointerType==="mouse")return;const rect=root.getBoundingClientRect();dragState={id:e.pointerId,startX:e.clientX,startY:e.clientY,left:rect.left,top:rect.top,moved:false};pet.setPointerCapture(e.pointerId)});
 pet.addEventListener("pointermove",e=>{if(!dragState||e.pointerId!==dragState.id)return;const dx=e.clientX-dragState.startX,dy=e.clientY-dragState.startY;if(Math.hypot(dx,dy)>7)dragState.moved=true;if(!dragState.moved)return;root.classList.add("po-manual-position");root.style.left=Math.max(0,Math.min(window.innerWidth-root.offsetWidth,dragState.left+dx))+"px";root.style.top=Math.max(0,Math.min(window.innerHeight-root.offsetHeight,dragState.top+dy))+"px";root.style.bottom="auto";root.style.right="auto"});
 pet.addEventListener("pointerup",e=>{if(!dragState||e.pointerId!==dragState.id)return;if(dragState.moved){ignoreClick=true;try{localStorage.setItem("englishapp:poPosition",JSON.stringify({x:parseFloat(root.style.left)/Math.max(1,innerWidth-root.offsetWidth),y:parseFloat(root.style.top)/Math.max(1,innerHeight-root.offsetHeight)}))}catch{}}dragState=null});
 pet.addEventListener("pointercancel",()=>dragState=null);
 pet.addEventListener("click",e=>{if(ignoreClick){e.stopImmediatePropagation();ignoreClick=false}},true);
 const restorePo=()=>{try{const pos=JSON.parse(localStorage.getItem("englishapp:poPosition")||"null");if(pos&&Number.isFinite(pos.x)&&Number.isFinite(pos.y)){root.classList.add("po-manual-position");root.style.left=Math.round(Math.max(0,Math.min(1,pos.x))*(innerWidth-root.offsetWidth))+"px";root.style.top=Math.round(Math.max(0,Math.min(1,pos.y))*(innerHeight-root.offsetHeight))+"px";root.style.bottom="auto"}}catch{}};
 restorePo();window.addEventListener("resize",restorePo);
 root.querySelector(".po-companion-toggle").onclick=()=>{root.classList.add("po-companion-hidden");try{localStorage.setItem("englishapp:poCompanionHidden","yes")}catch{}};
 root.querySelector(".po-companion-show").onclick=()=>{root.classList.remove("po-companion-hidden");try{localStorage.removeItem("englishapp:poCompanionHidden")}catch{};say("I'm back!","¡Ya volví!")};
 try{if(localStorage.getItem("englishapp:poCompanionHidden")==="yes")root.classList.add("po-companion-hidden")}catch{}
 }
 const inRoom=location.hash==="#po";root.classList.toggle("po-companion-in-room",inRoom);
}

function render(){let h=decodeURIComponent(location.hash.slice(1)||"home");if(h==="home"){stopStory();home()}else if(h==="po"){stopStory();poRoom()}else if(h==="stories")storiesHome();else if(/^stories-(A1|A2|B1|B2|C1|C2)$/.test(h))storyList(h.split("-")[1]);else if(/^story-(A1|A2|B1|B2|C1|C2)-\d+$/.test(h)){const p=h.split("-");storyPage(p[1],Number(p[2]))}else if(h==="a1")a1();else if(h==="grammar"||h==="vocabulary")blocks(h);else if(h.startsWith("grammar-block-")||h.startsWith("vocabulary-block-")){let p=h.split("-block-");block(p[0],+p[1])}else if(h.startsWith("lesson-")){let p=h.split("-"),kind=p[1],bi=+p[2],li=+p[3],name=DATA[kind][Object.keys(DATA[kind])[bi]][li];lesson(name,{href:`${kind}-block-${bi}`,label:"Lessons"})}else if(["speaking","listening","reading","writing","pronunciation","use-of-english","final-review"].includes(h)){let map={"speaking":"Speaking","listening":"Listening","reading":"Reading","writing":"Writing","pronunciation":"Pronunciation","use-of-english":"Use of English","final-review":"Final Review"};topics(map[h])}else if(h.startsWith("topic-")){let p=h.split("-"),name=p[1],i=+p[2],title=DATA.topics[name][i];lesson(title,{href:name.toLowerCase().replaceAll(" ","-"),label:name})}else if(h==="aviation")aviation();else if(h.startsWith("aviation-block-"))aviationBlock(+h.split("-").pop());else if(h.startsWith("aviation-lesson-")){let p=h.split("-"),bi=+p[2],li=+p[3],b=Object.keys(DATA.aviation)[bi];lesson(DATA.aviation[b][li],{href:"aviation-block-"+bi,label:b})}else if(h==="locked"){app.innerHTML=`${back("home","Home")}${hero("🔒 Coming next","We are completing A1 before opening the next level.")}`}else home();poCompanion()}
window.addEventListener("hashchange",render);render();